// Password gate shared by every page of the portfolio. Loaded after auth/config.js, which only holds the PBKDF2
// salt, the iteration count and the SHA-256 hash of the derived key: the password itself is never shipped.
// Protected pages are encrypted shells (AES-256-GCM, generated by tools/protect.mjs) that only this script can open.
(() => {
  const config = window.PORTFOLIO_AUTH;
  const sessionName = "portfolio_session";
  const script = document.currentScript;
  // auth/guard.js sits one level below the portfolio root (docs/).
  const root = new URL("../", script.src);

  const fromBase64 = (value) => Uint8Array.from(atob(value), (char) => char.charCodeAt(0));
  const toBase64 = (bytes) => {
    let binary = "";
    for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
    return btoa(binary);
  };

  async function deriveKey(password) {
    const material = await crypto.subtle.importKey("raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveBits"]);
    const bits = await crypto.subtle.deriveBits(
      { name: "PBKDF2", hash: "SHA-256", salt: fromBase64(config.salt), iterations: config.iterations },
      material,
      256
    );
    return toBase64(new Uint8Array(bits));
  }

  async function isValidKey(key) {
    try {
      const digest = await crypto.subtle.digest("SHA-256", fromBase64(key));
      return toBase64(new Uint8Array(digest)) === config.verifier;
    } catch {
      return false;
    }
  }

  // Payload layout: 12-byte IV, then the AES-256-GCM ciphertext (with its 16-byte tag) of the gzipped UTF-8 text.
  async function decrypt(key, payload) {
    const cryptoKey = await crypto.subtle.importKey("raw", fromBase64(key), "AES-GCM", false, ["decrypt"]);
    const bytes = fromBase64(payload);
    const zipped = await crypto.subtle.decrypt({ name: "AES-GCM", iv: bytes.subarray(0, 12) }, cryptoKey, bytes.subarray(12));
    const stream = new Blob([zipped]).stream().pipeThrough(new DecompressionStream("gzip"));
    return new Response(stream).text();
  }

  function clearSession() {
    try {
      localStorage.removeItem(sessionName);
    } catch {}
  }

  // Resolves to the stored key while the 7-day session is valid, otherwise to null.
  async function readSession() {
    let session = null;
    try {
      session = JSON.parse(localStorage.getItem(sessionName));
    } catch {}
    if (typeof session?.key === "string" && session.expires > Date.now() && (await isValidKey(session.key))) {
      return session.key;
    }
    clearSession();
    return null;
  }

  async function login(password) {
    const key = await deriveKey(password);
    if (!(await isValidKey(key))) throw new Error("Incorrect password.");
    const session = { key, expires: Date.now() + config.sessionDays * 86_400_000 };
    localStorage.setItem(sessionName, JSON.stringify(session));
    return key;
  }

  // Path of the current page relative to the portfolio root, e.g. "rationalization/index.html".
  function currentPath() {
    const path = location.pathname.startsWith(root.pathname) ? location.pathname.slice(root.pathname.length) : "";
    return decodeURIComponent(path) + location.search + location.hash;
  }

  // Only same-site relative paths are accepted, so ?next= can't be used to send users elsewhere.
  function resolveNext(next) {
    if (!next || /^[\\/]|^[a-z][a-z0-9+.-]*:|(^|[\\/])\.\.([\\/]|$)/i.test(next)) return null;
    const url = new URL(next, root);
    return url.origin === root.origin && url.pathname.startsWith(root.pathname) ? url.href : null;
  }

  function redirectToLanding() {
    const landing = new URL("index.html", root);
    const next = currentPath();
    if (next && !/^index\.html(?:$|[?#])/.test(next)) landing.searchParams.set("next", next);
    location.replace(landing.href);
  }

  // Opens an encrypted shell: replaces the document with the decrypted page, or sends the visitor to the login.
  async function unlockDocument() {
    const payload = window.__portfolioPayload;
    delete window.__portfolioPayload;
    const key = await readSession();
    if (!key || !payload) return redirectToLanding();
    let html;
    try {
      html = await decrypt(key, payload);
    } catch {
      clearSession();
      return redirectToLanding();
    }
    document.open();
    document.write(html);
    document.close();
  }

  window.PortfolioAuth = { root, login, readSession, clearSession, decrypt, resolveNext, redirectToLanding };

  if (script.hasAttribute("data-unlock")) unlockDocument();
})();
